	[TestMethod]
	public void flex_grow_less_than_factor_one()
	{
		var root = CreateNode();
		root.Style.PositionType = PositionType.Absolute;
		root.Style.Width = StyleLength.Points( 200 );
		root.Style.Height = StyleLength.Points( 500 );

		var root_child0 = CreateNode();
		root_child0.Style.FlexGrow = 0.2f;
		root_child0.Style.FlexBasis = StyleLength.Points( 40 );
		root.InsertChild( root_child0, 0 );

		var root_child1 = CreateNode();
		root_child1.Style.FlexGrow = 0.2f;
		root.InsertChild( root_child1, 1 );

		var root_child2 = CreateNode();
		root_child2.Style.FlexGrow = 0.4f;
		root.InsertChild( root_child2, 2 );
		root.CalculateLayout( float.NaN, float.NaN, Direction.LTR );

		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Left, "root.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Top, "root.Top" );
		AssertEq( 200, FixtureGeometry.GetRect( root, true ).Width, "root.Width" );
		AssertEq( 500, FixtureGeometry.GetRect( root, true ).Height, "root.Height" );

		AssertEq( 0, FixtureGeometry.GetRect( root_child0, true ).Left, "root_child0.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root_child0, true ).Top, "root_child0.Top" );
		AssertEq( 200, FixtureGeometry.GetRect( root_child0, true ).Width, "root_child0.Width" );
